def min_days(bloom: list[int], m: int, k: int) -> int:
    if m * k > len(bloom):
        return -1

    def can(day: int) -> bool:
        run = made = 0
        for b in bloom:
            if b <= day:
                run += 1
                if run == k:
                    made += 1
                    run = 0
            else:
                run = 0
        return made >= m

    lo, hi = min(bloom), max(bloom)
    while lo < hi:
        mid = lo + (hi - lo) // 2
        if can(mid):
            hi = mid
        else:
            lo = mid + 1
    return lo
